mapper.select:
SELECT k.id, k.category_id, k.question, k.answer, k.keywords, k.hit_count, k.status, k.create_time, k.update_time, c.name AS category_name FROM qa_knowledge k LEFT JOIN qa_category c ON c.id = k.category_id AND c.deleted = 0 WHERE k.deleted = 0
AND k.category_id = #{categoryId}
AND k.status = #{status}
AND (k.question LIKE CONCAT('%', #{keyword}, '%') OR k.keywords LIKE CONCAT('%', #{keyword}, '%') OR k.answer LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY k.update_time DESC, k.id DESC
